{"code":"import re, os, subprocess, glob
root='/home/runner/h-dashboard'
# map livewire blade files -> normalized name
comps={}
for p in glob.glob(root+'/resources/views/livewire/**/*.blade.php', recursive=True):
    rel=os.path.relpath(p, root+'/resources/views/livewire')
    name=re.sub(r'^.*/','',rel).replace('.blade.php','')
    comps[name]=rel
# gather test file text
tests={}
for p in glob.glob(root+'/tests/Feature/**/*.php', recursive=True)+glob.glob(root+'/tests/Unit/**/*.php', recursive=True):
    tests[os.path.relpath(p, root)]=open(p, encoding='utf-8', errors='replace').read()
alltests="\n".join(tests.values())
missing=[]
for name, rel in sorted(comps.items()):
    # search for Livewire::test('<name>') or ->get('name') etc
    hits=len(re.findall(re.escape(name), alltests))
    missing.append((hits, rel, name))
missing.sort()
for h,rel,name in missing:
    if h==0:
        print(f"ZERO  {rel}")
print('---- low (<=2) ----')
for h,rel,name in missing:
    if 0<h<=2:
        print(f"{h:3d}  {rel}")
print()
print("total comps:", len(comps))
"}

