{"content":"import re, os, glob
root='/home/runner/h-dashboard'
srcs=[]
for pat in ['app/**/*.php']:
    srcs += glob.glob(root+'/'+pat, recursive=True)
tests={}
for p in glob.glob(root+'/tests/**/*.php', recursive=True):
    if '/e2e/' in p: continue
    tests[p]=open(p, encoding='utf-8', errors='replace').read()
alltests="\n".join(tests.values())
rows=[]
for p in sorted(srcs):
    rel=os.path.relpath(p, root)
    cls=re.search(r'(?:class|trait|interface|enum)\s+(\w+)', open(p, encoding='utf-8', errors='replace').read())
    name=cls.group(1) if cls else os.path.basename(p)[:-4]
    rows.append((len(re.findall(r'\b'+re.escape(name)+r'\b', alltests)), rel, name))
rows.sort()
print("=== app classes with ZERO mention in PHP tests ===")
for h,rel,name in rows:
    if h==0: print("ZERO  ", rel)
print("=== 1-2 mentions ===")
for h,rel,name in rows:
    if 0<h<=2: print(f"{h:4d}  {rel}")
print("=== total app php files:", len(rows))
