3|namespace App\Services;
4|
5|use App\Models\HardwareAudit;
6|use Illuminate\Support\Collection;
7|use Illuminate\Support\Facades\DB;
8|
9|/**
10| * Organizational scope resolution for the hardware audit trail.
11| *
12| * Shared by the API (HardwareAuditController) and the Livewire
13| * hardware.index component (HardwareIndexHelpers) so both paths resolve
14| * scope — and deny — through exactly one implementation:
15| *
16| *   live hardware n_code → audit n_code snapshot → persons.u_id
17| *
18| * Deny by default: when the owning unit cannot be proven (no n_code, or a
19| * person that no longer exists) the audit is reported as out of scope.
20| */
21|class HardwareAuditScope
22|{
23|    /**
24|     * Unit that owns the hardware an audit refers to, null when unprovable.
25|     */
26|    public function unitIdForAudit(HardwareAudit $audit): ?int
27|    {
28|        return $this->unitIdsForAudits([$audit])[$audit->id] ?? null;
29|    }
30|
31|    /**
32|     * Is this audit's hardware inside the caller's accessible units?
33|     *
34|     * @param  array<int>  $accessibleIds
35|     */
36|    public function isAccessible(HardwareAudit $audit, array $accessibleIds): bool
37|    {
38|        $unitId = $this->unitIdForAudit($audit);
39|
40|        return $unitId !== null && in_array($unitId, $accessibleIds, true);
41|    }
42|
43|    /**
44|     * Batch variant — audit id => owning unit id (null when unprovable).
45|     *
46|     * Resolves every audit in three queries total, so a long trash list
47|     * never falls into a per-row N+1.
48|     *
49|     * @param  iterable<HardwareAudit>  $audits
50|     * @return array<int, int|null>
51|     */
52|    public function unitIdsForAudits(iterable $audits): array
53|    {
54|        $audits = collect($audits)->values();
55|
56|        if ($audits->isEmpty()) {
57|            return [];
58|        }
59|
60|        // 1. n_code: the live row when it still exists, otherwise the snapshot.
61|        $hardwareIds = $audits->pluck('hardware_id')->unique()->values()->all();
62|        /** @var Collection<int, string|null> $liveNCodes */
63|        $liveNCodes = DB::table('hardwares')->whereIn('id', $hardwareIds)->pluck('n_code', 'id');
