72|        $distinct = collect($nCodes)->filter()->unique()->values()->all();
73|        /** @var Collection<string, int|string|null> $unitByNCode */
74|        $unitByNCode = $distinct === []
75|            ? collect()
76|            : DB::table('persons')->whereIn('n_code', $distinct)->pluck('u_id', 'n_code');
77|
78|        $result = [];
79|        foreach ($nCodes as $auditId => $nCode) {
80|            $unitId = $nCode === null ? null : $unitByNCode->get($nCode);
81|            $result[$auditId] = $unitId === null ? null : (int) $unitId;
82|        }
83|
84|        return $result;
85|    }
