164|    public function restoreRecord(UnitScopedRequest $request, HardwareAudit $audit): JsonResponse
165|    {
166|        if ($audit->action !== 'created') {
167|            return response()->json(['message' => 'Only "created" audits can be used to restore a record.'], 422);
168|        }
169|
170|        // Verify the hardware was actually deleted. Use a direct query so this
171|        // works whether or not the Hardware model uses SoftDeletes.
172|        $exists = DB::table('hardwares')->where('id', $audit->hardware_id)->exists();
