3|namespace App\Http\Controllers\Api;
4|
5|use App\Exports\UnitsExport;
6|use App\Http\Requests\UnitScopedRequest;
7|use App\Models\Unit;
8|use Illuminate\Routing\Controller;
9|use Illuminate\Support\Collection;
10|use Maatwebsite\Excel\Facades\Excel;
11|use Symfony\Component\HttpFoundation\BinaryFileResponse;
12|
13|class UnitsExportController extends Controller
14|{
15|    /**
16|     * @return BinaryFileResponse
17|     */
18|    public function export(UnitScopedRequest $request)
19|    {
20|        $accessibleIds = $request->accessibleIds();
21|
22|        $units = Unit::query()
23|            ->with('unitType')
24|            // The «شهرستان» column reads region.name per row, so the relation
25|            // is eager-loaded here — otherwise the export issues one query per
26|            // unit, exactly the N+1 the other columns already avoid.
27|            ->with('region')
28|            ->when($accessibleIds === [], fn ($query) => $query->whereRaw('1 = 0'))
29|            ->when($accessibleIds !== [], fn ($query) => $query->whereIn('id', $accessibleIds))
30|            ->get();
31|
32|        // Ancestors above the caller's scope contribute names only to the
33|        // breadcrumb — the tree page already renders those, so nothing new
34|        // leaks — which is why this map covers every unit, not just the scope.
35|        $map = $this->hierarchyMap();
36|
37|        $hierarchy = $this->buildHierarchy($units, $map);
38|        $ordered = $this->orderDepthFirst($units);
39|
40|        $filename = 'units-'.now()->format('Ymd-His');
41|
42|        return Excel::download(new UnitsExport($ordered, $hierarchy), "{$filename}.xlsx");
43|    }
44|
45|    /**
46|     * Every unit's id → name/parent, loaded in one query so no row mapping ever
47|     * walks back to the database.
48|     *
49|     * @return array<int, array{name: string, parent_id: int|null}>
50|     */
51|    protected function hierarchyMap(): array
52|    {
53|        $map = [];
54|
55|        foreach (Unit::query()->get(['id', 'name', 'parent_id']) as $unit) {
56|            $map[$unit->id] = [
57|                'name' => $unit->name,
58|                'parent_id' => $unit->parent_id,
59|            ];
60|        }
61|
62|        return $map;
63|    }
64|
65|    /**
66|     * Breadcrumb, depth and parent name for every exported unit.
67|     *
68|     * `parent_id` is user-editable, so a bad edit can form a cycle. The visited
69|     * set stops the upward walk instead of looping forever.
70|     *
71|     * @param  Collection<int, Unit>  $units
72|     * @param  array<int, array{name: string, parent_id: int|null}>  $map
73|     * @return array<int, array{path: string, depth: int, parent_name: string}>
74|     */
75|    protected function buildHierarchy(Collection $units, array $map): array
76|    {
77|        $hierarchy = [];
78|
79|        foreach ($units as $unit) {
80|            $chain = [];
81|            $visited = [];
82|            $parentId = $unit->parent_id;
83|
84|            while ($parentId !== null && isset($map[$parentId]) && ! isset($visited[$parentId])) {
85|                $visited[$parentId] = true;
86|                array_unshift($chain, $map[$parentId]['name']);
87|                $parentId = $map[$parentId]['parent_id'];
88|            }
89|
90|            $hierarchy[$unit->id] = [
91|                'path' => implode(' > ', array_merge($chain, [$unit->name])),
92|                'depth' => count($chain),
93|                'parent_name' => $chain === [] ? '' : $chain[count($chain) - 1],
94|            ];
95|        }
96|
97|        return $hierarchy;
98|    }
99|
100|    /**
101|     * Sort parents before children so the sheet reads top-down. A unit whose
102|     * parent sits outside the exported set is a root, which also anchors a
103|     * scoped subtree at the caller's own unit.
104|     *
105|     * @param  Collection<int, Unit>  $units
106|     * @return Collection<int, Unit>
107|     */
108|    protected function orderDepthFirst(Collection $units): Collection
109|    {
110|        $byId = $units->keyBy('id');
111|
112|        /** @var array<int, list<Unit>> $children */
113|        $children = [];
114|        $roots = [];
115|
116|        foreach ($units as $unit) {
117|            $parentId = $unit->parent_id;
118|            if ($parentId !== null && $byId->has($parentId)) {
119|                $children[$parentId][] = $unit;
120|            } else {
121|                $roots[] = $unit;
122|            }
123|        }
124|
125|        // Siblings alphabetically, so a unit's row sits next to its same-named
126|        // neighbours rather than in arbitrary id order.
127|        $byName = fn (Unit $a, Unit $b) => strcmp((string) $a->name, (string) $b->name);
128|
129|        usort($roots, $byName);
130|        foreach ($children as &$siblings) {
131|            usort($siblings, $byName);
132|        }
133|        unset($siblings);
134|
135|        // A cycle leaves units with no reachable root. Append them by ascending
136|        // id so nothing is dropped from the file.
137|        $seen = [];
138|        foreach ($this->walk($roots, $children) as $unit) {
139|            $seen[$unit->id] = true;
140|        }
141|        $orphans = $units
142|            ->reject(fn (Unit $unit) => isset($seen[$unit->id]))
143|            ->sortBy('id')
144|            ->all();
145|
146|        $ordered = $this->walk($roots, $children);
147|
148|        return $ordered->concat(collect($orphans))->values();
149|    }
150|
151|    /**
152|     * @param  array<int, Unit>  $roots
153|     * @param  array<int, list<Unit>>  $children
154|     * @return Collection<int, Unit>
155|     */
156|    protected function walk(array $roots, array $children): Collection
157|    {
158|        $ordered = collect();
159|        $stack = $roots;
160|
161|        while ($stack !== []) {
162|            $unit = array_shift($stack);
163|            $ordered->push($unit);
164|
165|            foreach (array_reverse($children[$unit->id] ?? []) as $child) {
166|                array_unshift($stack, $child);
167|            }
168|        }
169|
170|        return $ordered;
171|    }
