22|    public function export(UnitScopedRequest $request)
23|    {
24|        $accessibleIds = $request->accessibleIds();
25|
26|        $query = Person::query()
27|            // Every lookup label in the sheet is a relation, so they are
28|            // eager-loaded here — otherwise the export issues one query per
29|            // person, exactly the N+1 the scope columns already avoid.
30|            ->with(['semat', 'tahsil', 'estekhdam', 'radif', 'unit'])
31|            ->when($accessibleIds === [], fn ($q) => $q->whereRaw('1 = 0'))
32|            ->when($accessibleIds !== [], fn ($q) => $q->whereIn('u_id', $accessibleIds));
33|
34|        $this->applySearch($query, $request);
35|        $this->applyFilters($query, $request);
36|
37|        /** @var Collection<int, Person> $persons */
38|        $persons = $query->orderBy('id')->get();
39|
40|        $filename = 'persons-'.now()->format('Ymd-His');
41|
42|        return Excel::download(new PersonsExport($persons), "{$filename}.xlsx");
43|    }
44|
45|    /**
46|     * The same multi-term search the personnel list runs, so the sheet and the
47|     * table on screen always agree about which rows match.
48|     *
49|     * Each whitespace-separated term must match (AND); within a term any of
50|     * n_code / "first last" / "last first" / unit name counts, so
51|     * "عسگری مهدی" finds «مهدی عسگری» too (#494).
52|     *
53|     * @param  Builder<Person>  $query
54|     */
55|    protected function applySearch(Builder $query, UnitScopedRequest $request): void
56|    {
57|        $search = trim((string) $request->input('search', ''));
58|
59|        if ($search === '') {
60|            return;
61|        }
62|
63|        // normalizeForQuery normalizes Persian/Arabic chars + escapes LIKE wildcards.
64|        $normalized = self::normalizeForQuery($search);
65|
66|        $terms = array_values(array_filter(explode(' ', $normalized), fn (string $term) => $term !== ''));
67|        // Persons/n_code columns are PersianNormalizer-hooked on save; the unit
68|        // name column is not, so its filter must fold the column (#815). Build
69|        // the unit term from the RAW term — re-escaping an already-escaped term
70|        // would double-escape LIKE wildcards.
71|        $rawTerms = array_values(array_filter(explode(' ', trim($search)), fn (string $t) => $t !== ''));
72|        $foldedTerms = array_map(static fn (string $term): string => self::foldedTerm($term), $rawTerms);
73|
74|        if ($terms === []) {
75|            return;
76|        }
77|
78|        $query->where(function (Builder $outer) use ($terms, $foldedTerms): void {
79|            foreach ($terms as $i => $term) {
80|                $foldedTerm = $foldedTerms[$i];
81|                $outer->where(function (Builder $termQuery) use ($term, $foldedTerm): void {
82|                    // whereHas first: it is declared on the Eloquent builder and
83|                    // returns $this, so the OR group below keeps its type. The
84|                    // orWhereRaw() calls are forwarded to the query builder and
85|                    // would degrade the chain's type mid-expression.
86|                    $termQuery->whereHas('unit', function (Builder $unitQuery) use ($foldedTerm): void {
87|                        $unitQuery->whereRaw(self::foldSeparatorsSql('name').' LIKE ?', ["%{$foldedTerm}%"]);
88|                    });
89|
90|                    $termQuery->orWhere('n_code', 'LIKE', "%{$term}%")
91|                        ->orWhereRaw("CONCAT(f_name, ' ', l_name) LIKE ?", ["%{$term}%"])
92|                        ->orWhereRaw("CONCAT(l_name, ' ', f_name) LIKE ?", ["%{$term}%"]);
93|                });
94|            }
95|        });
96|    }
97|
98|    /**
99|     * The #494 list filters. They narrow the accessible scope, never widen it:
100|     * a unit id outside accessibleUnitIds() simply matches no row.
101|     *
102|     * @param  Builder<Person>  $query
103|     */
104|    protected function applyFilters(Builder $query, UnitScopedRequest $request): void
105|    {
106|        $filters = [
107|            'filter_u_id' => 'u_id',
108|            'filter_s_id' => 's_id',
109|            'filter_t_id' => 't_id',
110|            'filter_e_id' => 'e_id',
111|            'filter_r_id' => 'r_id',
112|        ];
113|
114|        foreach ($filters as $parameter => $column) {
115|            $value = $request->input($parameter);
116|
117|            if ($value !== null && $value !== '') {
118|                $query->where($column, $value);
119|            }
120|        }
121|    }
